int count = 0;
Node* current = root;
while (current != nullptr) {
    if (level == 0) {
        count += current->keys.size();
    }
    if (level > 0) {
        if (current->isLeaf) {
            break;
        }
        level--;
        if (current->children.size() > 0) {
            current = current->children[0];
        } else {
            break;
        }
    }
}
return count;

